import { Routes } from "@angular/router";

export const mainRoutes: Routes = [
  {
    path: '',
    redirectTo: 'inicio',
    pathMatch: 'full'
  },
  {
    path: 'inicio',
    loadComponent: () => import('./inicio/inicio.component').then(c => c.InicioComponent)
  },
  {
    path: 'usuarios',
    title: 'Usuarios',
    loadChildren: () => import('./usuarios/usuarios.routes').then(m => m.usuariosRoutes)
  },
  {
    path: 'externos',
    title: 'Externos',
    loadChildren: () => import('./externos/externos.routes').then(m => m.externosRoutes)
  },
]